class BrowserWorker(Agent):
    """A separate model conversation confined to one supplied browser; no scripted navigation."""
    def __init__(self, parent, browser_index, task):
        if type(browser_index) is not int or not 0 <= browser_index < len(parent.browser.browsers):
            raise ValueError("Unknown worker browser")
        super().__init__(parent.browser, parent.book, parent.run, prepare_only=True, clef=parent.clef)
        self.browser_index = browser_index
        self.task = task
        self.trace = parent.trace
        self.log_secrets = parent.log_secrets

    async def dispatch(self, name, args):
        if name == "report":
            self.notes.append(args["text"])
            self.done = True
            return {"status": "worker_reported"}
        if name not in {"browser", "cite", "resolve", "decide", "note", "notebook"}:
            raise ValueError("Workers gather evidence only; submission belongs to the coordinator")
        if name == "browser":
            args = dict(args)
            if args["operation"] == "pages":
                return [p for p in self.browser.page_list() if p["browser"] == self.browser_index]
            if args["operation"] in {"new_tab", "new_context"}:
                args["browser"] = self.browser_index
            else:
                page = args.get("page")
                ref = args.get("ref")
                if args.get("fields"):
                    ref = args["fields"][0]["ref"]
                if ref in self.browser.controls:
                    page = self.browser.controls[ref][0]
                if page is None:
                    page = next(p["page"] for p in self.browser.page_list() if p["browser"] == self.browser_index)
                if self.browser.browser_index(self.browser.page(page)) != self.browser_index:
                    raise ValueError("Worker cannot act in another browser")
                args["page"] = page
        return await super().dispatch(name, args)


